sys.dont_write_bytecode = True
os.environ["PYTHONDONTWRITEBYTECODE"] = "1"
os.environ["GIT_TERMINAL_PROMPT"] = "0"


def ensure_writable(path: str) -> None:
    """Ensure owner has write permissions on directories and files under path."""
    if not os.path.exists(path):
        return
    try:
        st = os.lstat(path)
        if not stat.S_ISLNK(st.st_mode):
            if stat.S_ISDIR(st.st_mode):
                os.chmod(path, st.st_mode | stat.S_IRWXU)
            else:
                os.chmod(path, st.st_mode | stat.S_IRUSR | stat.S_IWUSR)
    except OSError:
        pass
    for root, dirs, files in os.walk(path):
        for d in dirs:
            dp = os.path.join(root, d)
            try:
                st = os.lstat(dp)
                if not stat.S_ISLNK(st.st_mode):
                    os.chmod(dp, st.st_mode | stat.S_IRWXU)
            except OSError:
                pass
        for f in files:
            fp = os.path.join(root, f)
            try:
                st = os.lstat(fp)
                if not stat.S_ISLNK(st.st_mode):
                    os.chmod(fp, st.st_mode | stat.S_IRUSR | stat.S_IWUSR)
            except OSError:
                pass


