    cmd = [
        "git",
        "-c", "safe.directory=*",
        "-c", "core.hooksPath=/dev/null",
        "-c", "gc.auto=0",
        "-c", "gc.autoDetach=false",
        "-c", "gc.cruftPacks=false",
        "-C", repo,
        *args,
    ]
    return subprocess.run(
        cmd,
        input=input_text,
        capture_output=True,
        text=True,
        check=check,
    )


def get_upstream_tips(repo: str, git_dir: str) -> set[str]:
    """Collect commit SHAs from ORIG_HEAD, FETCH_HEAD, remotes, tags, and clone reflogs."""
    tips: set[str] = set()
    for fn in ("ORIG_HEAD", "FETCH_HEAD"):
        fp = os.path.join(git_dir, fn)
        if os.path.isfile(fp):
            try:
                with open(fp, "r", errors="replace") as f:
                    for line in f:
                        tok = line.strip().split()
                        if tok and len(tok[0]) == 40:
                            tips.add(tok[0])
            except OSError:
                pass

    logs_dir = os.path.join(git_dir, "logs")
    if os.path.isdir(logs_dir):
        for root, _, files in os.walk(logs_dir):
            for fn in files:
                fp = os.path.join(root, fn)
                try:
                    with open(fp, "r", errors="replace") as f:
                        for line in f:
                            if "\tclone:" in line:
                                parts = line.split()
                                if len(parts) >= 2 and len(parts[1]) == 40:
                                    tips.add(parts[1])
                except OSError:
                    pass

