    if tips:
        proc = run_git(
            repo,
            "cat-file",
            "--batch-check=%(objectname) %(objecttype)",
            check=False,
            input_text="\n".join(tips) + "\n",
        )
        if proc.returncode == 0:
            for line in proc.stdout.splitlines():
                parts = line.split()
                if len(parts) == 2 and parts[1] in ("commit", "tag"):
                    valid_tips.add(parts[0])
