    short_head_before = run_git(repo, "rev-parse", "--short", "HEAD", check=False).stdout.strip()
    abbrev_before = len(short_head_before) if short_head_before else 0
    explicit_abbrev = run_git(repo, "config", "--get", "core.abbrev", check=False).stdout.strip()

    head = run_git(repo, "rev-parse", "--verify", "HEAD^{commit}").stdout.strip()
    sym_head_res = run_git(repo, "symbolic-ref", "-q", "HEAD", check=False)
    sym_head = sym_head_res.stdout.strip() if sym_head_res.returncode == 0 else ""

    anc_bc = set(run_git(repo, "rev-list", bc).stdout.splitlines())
    anc_head = set(run_git(repo, "rev-list", head).stdout.splitlines())

    # Determine whether HEAD is at base_commit or has synthetic builder commit(s) on top of base_commit
    keep_head = False
    if head == bc:
        keep_head = True
    elif bc in anc_head:
        commits_after_bc = anc_head - anc_bc
        upstream_tips = get_upstream_tips(repo, git_dir)
        upstream_anc: set[str] = set()
        if upstream_tips:
            res = run_git(repo, "rev-list", *upstream_tips, check=False)
            if res.returncode == 0:
                upstream_anc = set(res.stdout.splitlines())

        # Also check if any commit in the object DB outside anc_head has a parent in commits_after_bc
        all_commits_res = run_git(repo, "cat-file", "--batch-check=%(objectname) %(objecttype)", "--batch-all-objects", check=False)
        all_commit_shas = [
            l.split()[0] for l in all_commits_res.stdout.splitlines() if l.endswith(" commit") and l.split()[0] not in anc_head
        ]
        has_external_child = False
        if all_commit_shas:
            parents_res = run_git(
                repo,
                "cat-file",
                "--batch=%(objectname)",
                check=False,
                input_text="\n".join(all_commit_shas) + "\n",
            )
            # Fast parent check via rev-list --parents --no-walk
            rev_parents = run_git(
                repo,
                "rev-list",
                "--no-walk",
                "--parents",
                "--stdin",
                check=False,
                input_text="\n".join(all_commit_shas) + "\n",
            )
            if rev_parents.returncode == 0:
                for line in rev_parents.stdout.splitlines():
                    parts = line.split()
                    if any(p in commits_after_bc for p in parts[1:]):
                        has_external_child = True
                        break

        if not (commits_after_bc & upstream_anc) and not has_external_child:
            keep_head = True

    if not keep_head:
        if sym_head:
            run_git(repo, "reset", "--hard", bc)
        else:
            run_git(repo, "checkout", "-f", bc)
        head = bc
        anc_head = anc_bc

    allowed_commits = anc_bc | anc_head

